export func recurse(n) { if n == 0 { return locked[0] } return recurse(n - 1) }
export func reject() { locked[0] = 9 }
export func invoke(callback) { return callback(locked) }
export func factory(value) {
    mut items := [value]
    let saved := func() { return items[0] }
    items[0] = 99
    return saved
}

